// Local server for the UI capture: serves the production build of the SPA,
// a same-origin media mirror at /media (content generated by gen-content.mjs),
// and stubs for the Cloudflare Workers the browser talks to
// (llm-proxy /v1/*, community votes, stats/beacons).
import http from 'node:http';
import { readFileSync, existsSync, statSync, createReadStream } from 'node:fs';
import { join, extname, normalize } from 'node:path';
import { llmReply, councilReply, summaryReply } from './stubs/llm.mjs';

const ROOT = new URL('..', import.meta.url).pathname;
const BUILD = join(ROOT, 'client/build');
const ASSETS = join(ROOT, 'client/src/assets');
const MEDIA = join(ROOT, '.ui-capture/media');
const PORT = Number(process.env.PORT || 4488);

const TYPES = {
  '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.mjs': 'text/javascript',
  '.css': 'text/css', '.json': 'application/json; charset=utf-8', '.svg': 'image/svg+xml',
  '.png': 'image/png', '.webp': 'image/webp', '.avif': 'image/webp', '.jpg': 'image/webp',
  '.woff2': 'font/woff2', '.txt': 'text/plain; charset=utf-8', '.mp3': 'audio/wav', '.webm': 'audio/wav',
  '.wav': 'audio/wav', '.xml': 'application/xml', '.ico': 'image/x-icon',
};

const MEDIA_MAP = [
  ['seeds/', join(ASSETS, 'translations/seeds')],
  ['figure-translations/', join(ASSETS, 'translations/figures')],
  ['factchecks/', join(ASSETS, 'factchecks')],
  ['voice-profiles/', join(ASSETS, 'voice_profiles')],
  ['instructions/', join(ASSETS, 'instructions')],
  ['stories/', join(ASSETS, 'stories')],
  ['prisms/', join(ASSETS, 'prisms')],
  ['', MEDIA],
];

function sendFile(req, res, file, extraHeaders = {}) {
  const st = statSync(file);
  const type = TYPES[extname(file)] || 'application/octet-stream';
  const headers = { 'Content-Type': type, 'Accept-Ranges': 'bytes', 'Cache-Control': 'no-cache',
    'Access-Control-Allow-Origin': '*', 'Cross-Origin-Resource-Policy': 'cross-origin', ...extraHeaders };
  const range = req.headers.range && /bytes=(\d*)-(\d*)/.exec(req.headers.range);
  if (range) {
    const start = range[1] ? Number(range[1]) : 0;
    const end = range[2] ? Math.min(Number(range[2]), st.size - 1) : st.size - 1;
    res.writeHead(206, { ...headers, 'Content-Range': `bytes ${start}-${end}/${st.size}`, 'Content-Length': end - start + 1 });
    if (req.method === 'HEAD') return res.end();
    return createReadStream(file, { start, end }).pipe(res);
  }
  res.writeHead(200, { ...headers, 'Content-Length': st.size });
  if (req.method === 'HEAD') return res.end();
  createReadStream(file).pipe(res);
}

function json(res, code, body, headers = {}) {
  res.writeHead(code, { 'Content-Type': 'application/json', 'X-AI-Generated': 'true', ...headers });
  res.end(JSON.stringify(body));
}

function readBody(req) {
  return new Promise((resolve) => {
    let data = '';
    req.on('data', (c) => (data += c));
    req.on('end', () => { try { resolve(JSON.parse(data || '{}')); } catch { resolve({}); } });
  });
}

function isFile(p) { try { return statSync(p).isFile(); } catch { return false; } }

function serveMedia(req, res, rel) {
  rel = normalize(rel).replace(/^\/+/, '');
  if (rel.includes('..')) return json(res, 400, { error: 'bad path' });
  // Images: one generated webp per figure/ui/background; all widths and
  // formats map onto it.
  let m = /^images\/figures\/([a-z]+)\/(main|thumbnail)[^/]*\/\d+\.\w+$/.exec(rel);
  if (m) {
    const f = join(MEDIA, 'images/figures', m[1], `${m[2]}.webp`);
    if (isFile(f)) return sendFile(req, res, f);
  }
  m = /^images\/(ui|icons|backgrounds)\/([^/]+)\/\d+\.\w+$/.exec(rel);
  if (m) {
    const f = join(MEDIA, 'images', m[1], `${m[2]}.webp`);
    if (isFile(f)) return sendFile(req, res, f);
  }
  // Every recorded audio file (story, prism, council, trailer, greeting)
  // is served from one narrated-length placeholder recording.
  if (/\.(mp3|webm|m4a|opus|ogg)$/.test(rel)) {
    const txt = rel.replace(/\.(mp3|webm|m4a|opus|ogg)$/, '.txt');
    const hasText = MEDIA_MAP.some(([p, dir]) => rel.startsWith(p) && isFile(join(dir, txt.slice(p.length))));
    const isCatalogAudio = /^(prisms|councils|trailers|initial-messages|voice-previews|forewords)\//.test(rel);
    if (hasText || isCatalogAudio) return sendFile(req, res, join(MEDIA, 'audio/narration.wav'));
  }
  for (const [prefix, dir] of MEDIA_MAP) {
    if (!rel.startsWith(prefix)) continue;
    const f = join(dir, rel.slice(prefix.length));
    if (isFile(f)) return sendFile(req, res, f);
  }
  res.writeHead(404, { 'Access-Control-Allow-Origin': '*' });
  res.end('not found');
}

let quotaUsed = 7;

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://localhost:${PORT}`);
  const p = decodeURIComponent(url.pathname);
  if (process.env.UICAP_LOG) console.log(req.method, p);

  if (req.method === 'OPTIONS') {
    res.writeHead(204, { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': '*', 'Access-Control-Allow-Methods': '*' });
    return res.end();
  }

  if (p.startsWith('/media/')) return serveMedia(req, res, p.slice('/media/'.length));

  // ---- llm-proxy worker stub (free tier) ----
  if (p === '/v1/session') {
    return json(res, 200, { token: 'local-session-' + Date.now().toString(36), expiresAt: new Date(Date.now() + 600_000).toISOString(), clientId: 'c-7f3a91d2e4b8' });
  }
  if (p === '/v1/quota') {
    return json(res, 200, { daily: { used: quotaUsed, limit: 30, resetsAt: new Date(Date.now() + 6 * 3600_000).toISOString() }, council: { used: 0, limit: 1 }, summary: { used: 1, limit: 2 }, freeTier: true });
  }
  if (p.startsWith('/v1/chat')) {
    const body = await readBody(req);
    quotaUsed = Math.min(30, quotaUsed + 1);
    return llmReply(req, res, body, { used: quotaUsed, limit: 30 });
  }
  if (p.startsWith('/v1/council')) return councilReply(req, res, await readBody(req));
  if (p.startsWith('/v1/summary')) return summaryReply(req, res, await readBody(req));
  if (p.startsWith('/v1/audio')) return json(res, 503, { error: 'live_audio_retired' });
  // beacons / stats / conversions: accept and drop, like the aggregate counters do
  if (p.startsWith('/v1/') || p.startsWith('/api/')) {
    if (req.method === 'POST') await readBody(req);
    res.writeHead(204, { 'Access-Control-Allow-Origin': '*' });
    return res.end();
  }
  // ---- community worker stub ----
  if (p.startsWith('/community/')) {
    const tally = JSON.parse(readFileSync(join(ROOT, '.ui-capture/stubs/community.json'), 'utf8'));
    return json(res, 200, tally);
  }

  if (p === '/healthz') { res.writeHead(200); return res.end('ok'); }
  if (p === '/__uicap/seed.js') return sendFile(req, res, join(ROOT, '.ui-capture/seed/seed.js'));

  // ---- static SPA ----
  if (p === '/' || p === '/index.html') { res.writeHead(302, { Location: '/app' }); return res.end(); }
  const f = join(BUILD, normalize(p));
  if (f.startsWith(BUILD) && isFile(f)) return sendFile(req, res, f);
  if (p.startsWith('/assets/')) { res.writeHead(404); return res.end(); }
  // SPA shell, with the returning-listener seed loaded ahead of the bundle
  const html = readFileSync(join(BUILD, 'index.html'), 'utf8')
    .replace('<script src="/splash-lang.js"></script>', '<script src="/__uicap/seed.js"></script><script src="/splash-lang.js"></script>');
  res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-cache' });
  return res.end(html);
});

server.listen(PORT, '127.0.0.1', () => console.log(`Agora Cosmica (local) on http://localhost:${PORT}/app`));
